// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/ai-agents", wrapper.ListAiAgents)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/ai-agents", wrapper.CreateAiAgent)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/ai-agents/{agentId}", wrapper.DeleteAiAgent)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/ai-agents/{agentId}", wrapper.GetAiAgent)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/ai-agents/{agentId}", wrapper.UpdateAiAgent)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/ai-agents/{agentId}/assign", wrapper.AssignAiAgent)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/git-connections", wrapper.ListGitConnections)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/git-connections", wrapper.CreateGitConnection)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/git-connections/{connectionId}", wrapper.DeleteGitConnection)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/git-connections/{connectionId}", wrapper.UpdateGitConnection)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/git-connections/{connectionId}/check", wrapper.CheckGitConnection)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/git-connections/{connectionId}/repos", wrapper.ListRemoteRepos)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/git-connections/{connectionId}/webhook", wrapper.GetGitWebhook)
	})

	return r
}
